#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

typedef struct TreeNode {
    int val;
    struct TreeNode *left;
    struct TreeNode *right;
} TreeNode;

static TreeNode *newNode(int val) {
    TreeNode *node = (TreeNode *)malloc(sizeof(TreeNode));
    if (!node) exit(EXIT_FAILURE);
    node->val = val;
    node->left = NULL;
    node->right = NULL;
    return node;
}

static char *trim(char *s) {
    while (*s && isspace((unsigned char)*s)) s++;
    char *end = s + strlen(s);
    while (end > s && isspace((unsigned char)end[-1])) end--;
    *end = '\0';
    return s;
}

static TreeNode *buildTree(char *line) {
    size_t len = strlen(line);
    while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r')) {
        line[--len] = '\0';
    }

    if (len < 4) return NULL;          /* only valid inputs such as [[]] */
    line[len - 2] = '\0';              /* remove inner closing ']' */
    char *body = line + 2;             /* skip outer '[[' */

    char *tok = strtok(body, ",");
    if (tok == NULL || strcmp(trim(tok), "") == 0) return NULL;

    TreeNode *root = newNode(atoi(trim(tok)));
    TreeNode **queue = (TreeNode **)malloc(10000 * sizeof(TreeNode *));
    if (!queue) exit(EXIT_FAILURE);

    int front = 0, back = 0;
    queue[back++] = root;

    while (front < back) {
        TreeNode *node = queue[front++];

        tok = strtok(NULL, ",");
        if (tok == NULL) break;
        tok = trim(tok);
        if (strcmp(tok, "null") != 0) {
            node->left = newNode(atoi(tok));
            queue[back++] = node->left;
        }

        tok = strtok(NULL, ",");
        if (tok == NULL) break;
        tok = trim(tok);
        if (strcmp(tok, "null") != 0) {
            node->right = newNode(atoi(tok));
            queue[back++] = node->right;
        }
    }

    free(queue);
    return root;
}

/**
 * Return the number of nodes on the longest root-to-leaf path.
 */
int maxDepth(TreeNode *root) {
    if (root == NULL) return 0;

    TreeNode **queue = (TreeNode **)malloc(10000 * sizeof(TreeNode *));
    int *depths = (int *)malloc(10000 * sizeof(int));
    if (!queue || !depths) exit(EXIT_FAILURE);

    int front = 0, back = 0;
    int answer = 0;
    queue[back] = root;
    depths[back++] = 1;

    while (front < back) {
        TreeNode *node = queue[front];
        int d = depths[front++];

        if (d > answer) answer = d;

        if (node->left != NULL) {
            queue[back] = node->left;
            depths[back++] = d + 1;
        }
        if (node->right != NULL) {
            queue[back] = node->right;
            depths[back++] = d + 1;
        }
    }

    free(queue);
    free(depths);
    return answer;
}

