static TreeNode* buildTree(const string& line) {
    string s = line;
    while (!s.empty() && (s.back() == '\n' || s.back() == '\r')) s.pop_back();

    string body = s.substr(2, s.size() - 4);  // from [[...]] to ...
    if (body.empty()) return nullptr;

    vector<string> parts;
    size_t start = 0;
    for (size_t i = 0; i <= body.size(); ++i) {
        if (i == body.size() || body[i] == ',') {
            parts.push_back(body.substr(start, i - start));
            start = i + 1;
        }
    }

    auto trim = [](string x) {
        size_t a = 0, b = x.size();
        while (a < b && isspace(static_cast<unsigned char>(x[a]))) ++a;
        while (b > a && isspace(static_cast<unsigned char>(x[b - 1]))) --b;
        return x.substr(a, b - a);
    };

    string first = trim(parts[0]);
    if (first.empty() || first == "null") return nullptr;

    TreeNode* root = new TreeNode(stoi(first));
    queue<TreeNode*> q;
    q.push(root);

    size_t i = 1;
    while (!q.empty() && i < parts.size()) {
        TreeNode* node = q.front();
        q.pop();

        string left = trim(parts[i++]);
        if (left != "null" && !left.empty()) {
            node->left = new TreeNode(stoi(left));
            q.push(node->left);
        }

        if (i < parts.size()) {
            string right = trim(parts[i++]);
            if (right != "null" && !right.empty()) {
                node->right = new TreeNode(stoi(right));
                q.push(node->right);
            }
        }
    }

    return root;
}

